function UIMainBattlePanelDialog:__init()
    self._curSelectInd = 0
    self._curSelectChildInd = 0
    self._curSelectMainType = 0
end

function UIMainBattlePanelDialog:__delete()
    self._curSelectInd = nil
    self._curSelectChildInd = nil
    self._curSelectMainType = nil
end

function UIMainBattlePanelDialog:Awake()
    SetButtonAction(self.BtnReward, Bind(self, self.OnBtnReward))
    SetButtonAction(self.BtnNormal, Bind(self, self.OnBtnNormalClick))
    SetButtonAction(self.BtnHard, Bind(self, self.OnBtnHardClick))
    local isOpen = CfUtils.IsOpneByFunctionId(10001)
    CfUtils.SetActive(self.BtnHard, isOpen)
    ---@type QuestComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
    comp:UpdateChallengeRedPoint()
    GameUtils.BindRedPoint(Constants.RedPointConst.MainHardQuest ,self.BtnHard.transform:Find("Root").gameObject,true,nil,function(node)
        local redGo = GameUtils.GetRedPointGo(self.BtnHard.transform:Find("Root").gameObject)
        KTool.SetActive(redGo.gameObject,node.pointNum > 0)
    end)
end

function UIMainBattlePanelDialog:OnBtnReward(isUnlockChapter)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIMainBattleChapterRewardPopupDialog, parameters = {isUnlockChapter = isUnlockChapter == true} }, {
        --{id = Constants.UITypeIds.UIMainBattlePanelDialog}
    })
end

function UIMainBattlePanelDialog:OnBtnNormalClick()
    if self._curSelectMainType == Constants.IDType.QuestMain then
        return
    end
    self._curSelectMainType = Constants.IDType.QuestMain
    self:InitSelectUI()
    self:FillSelf()
end

function UIMainBattlePanelDialog:OnBtnHardClick()
    if self._curSelectMainType == Constants.IDType.QuestMainChallenge then
        return
    end

    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id245)
    if not isUnlock then
        GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id245))
        return
    end

    self._curSelectMainType = Constants.IDType.QuestMainChallenge
    self:InitSelectUI()
    self:FillSelf()
end

function UIMainBattlePanelDialog:OnFocus(focus)
    if focus then
        -- if checkNumber(self._curSelectInd) == 1 then
        --     CfUtils.RefreshTopGoods({ Constants.Currency.FreeDiamondId, Constants.Currency.HpId })
        -- else
        --     CfUtils.RefreshTopGoods({})
        -- end

        local go = GameUtils.GetRedPointGo(self.BtnReward)
        CfUtils.SetActive(go, QuestConfMgr:GetInstance():IsHasCanDrawChapterReward())
        local go = GameUtils.GetRedPointGo(self.BtnNormal.transform:Find("Root").gameObject)
        if not isNull(go) then
            CfUtils.SetActive(go, QuestConfMgr:GetInstance():IsHasCanDrawChapterReward())
        end

        if self._isShowPassAni and not self._isShowRward then
            self._isShowRward = true
            local scr = CfUtils.GetLuaScr(self.PerspectivePanel, "Game.UI.FightReady.UIMainChapter.UIMainBattlePanel.UIMainQuestNode")
            if scr then
                scr:RefreshPos()
            end
        end
    end
end

function UIMainBattlePanelDialog:InitSelectData()
    local ind = checkNumber(KCookie.Get("UIMainBattlePanelDialogIndex"))
    if ind > 0 then
        self._curSelectInd = ind
    end
    ind = checkNumber(KCookie.Get("UIMainBattlePanelDialogChildIndex"))
    if ind > 0 then
        self._curSelectChildInd = ind
    end

    KCookie.Set("UIMainBattlePanelDialogIndex", 0)
    KCookie.Set("UIMainBattlePanelDialogChildIndex", 0)

    if checkNumber(self._curSelectInd) == 0 then
        self._curSelectInd = 1
    end
    if checkNumber(self._curSelectChildInd) == 0 then
        self._curSelectChildInd = 1
    end
end

function UIMainBattlePanelDialog:FillSelf()
    self:FillMainQuest()
end

function UIMainBattlePanelDialog:FillMainQuest()
    ---@type UIMainQuestNode
    local scr = CfUtils.GetLuaScr(self.PerspectivePanel, "Game.UI.FightReady.UIMainChapter.UIMainBattlePanel.UIMainQuestNode")
    if scr then
        scr:Refresh(self._curSelectMainType,self.controller)
    end
end

function UIMainBattlePanelDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if checkNumber(KCookie.Get("MainQuestLastPassChapter")) > 0 and not self._isShowPassAni then
            coroutine.yield(WaitForSeconds(0.3))
            self:OnBtnReward(true)
            self._isShowPassAni = true
            
        end
    end))
    return coWait
end

function UIMainBattlePanelDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if argument then
            self._curSelectInd = checkNumber(argument.index)
            self._curSelectMainType = checkNumber(argument.type)

            --self._curSelectChildInd = checkNumber(KCookie.Get("UIMainBattlePanelDialogRoleChildInd"))
            --KCookie.Set("UIMainBattlePanelDialogRoleChildInd", 0)
        end

        if checkNumber(self._curSelectMainType) == 0 then
            local type = checkNumber(KCookie.Get("MainQuestType"))
            if type > 0 then
                self._curSelectMainType = type
            else
                self._curSelectMainType = Constants.IDType.QuestMain
            end
        end
        CfUtils.SetUICameraProjection(false, 26)
        self:InitSelectData()
        self:InitSelectUI()
        self:FillSelf()

        -- 播放主线章节BGM
        local bgmId = QuestConfMgr:GetInstance():GetCurrentMainChapterBGM()
        if not string.isEmpty(bgmId) then
            CriWareUtils.PlayMusicById(bgmId)
        end
    end))
    return coWait
end

function UIMainBattlePanelDialog:InitSelectUI()
    local isNormal = self._curSelectMainType == Constants.IDType.QuestMain
    KTool.SetActive(self.BtnReward,isNormal)
    self:FillSelectBtn(isNormal)
    local aniName = isNormal and "MainChapterDialog_NormalStory" or "MainChapterDialog_HardStory"
    CfUtils.PlayAnimation(self.controller,aniName)
end

function UIMainBattlePanelDialog:FillSelectBtn(isNormal)
    local vo = CfUtils.SystemToggleVo( Constants.SystemToggleIds.Id245)
    --如果是关闭
    if checkNumber(vo.switch) == Constants.ModelFunctionSwitch.Off then
        CfUtils.SetActive(self.BtnNormal.gameObject,false)
        CfUtils.SetActive(self.BtnHard.gameObject,false)
        return
    end

    CfUtils.SetActive(self.BtnNormal.gameObject,true)
    CfUtils.SetActive(self.BtnHard.gameObject,true)
    local aniName = isNormal and "MainBattlePanel_BtnSelect" or "MainBattlePanel_BtnSelectDefualt"
    self:FillBtn(self.BtnNormal,aniName,isNormal,true)
    aniName = isNormal and "MainBattlePanel_BtnSelectDefualt" or "MainBattlePanel_BtnSelect"

    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id245)
    self:FillBtn(self.BtnHard,aniName,not isNormal,isUnlock)
end

function UIMainBattlePanelDialog:FillBtn(btn,ani,status,isUnLock)
    local isOpen = CfUtils.IsOpneByFunctionId(10001)
    if not isOpen then
        return
    end
    local root = btn.transform:Find("Root")
    if not isNull(root) then
        local imageSymbol = root.transform:Find("ImgSymbol")
        local imgLock = root.transform:Find("ImgLock")
        local imgSelect = root.transform:Find("ImgDeco")
        local imgBg = root.transform:Find("ImgBg")
        KTool.SetActive(imgLock.gameObject,not isUnLock)
        if not isUnLock then
            CfUtils.SetUISwitchImage(imageSymbol,2)
            CfUtils.SetUISwitchImage(imgBg,3)
            CfUtils.PlayAnimation(root,"MainBattlePanel_BtnSelectDefualt")
            KTool.SetActive(imgSelect.gameObject,false)
            return
        end
        CfUtils.PlayAnimation(root,ani)
        CfUtils.SetActive(imgSelect.gameObject,status)
        CfUtils.SetUISwitchImage(imgBg,status and 1 or 2)
        CfUtils.SetUISwitchImage(imageSymbol,status and 1 or 2)
    end
end

function UIMainBattlePanelDialog:IsHasRoleReward()
    for k, v in pairs(RoleQuestCf) do
        for _, _id in pairs(v.roleIds) do
            if self:IsShow(_id) then
                if QuestConfMgr:GetInstance():IsRoleHasDrawRewardId(_id) or PhoneUtils.IsRoleUnlockRedPoint(_id) then
                    return 1
                end
            end
        end
    end
    return 0
end

function UIMainBattlePanelDialog:IsShow(id)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting851, "RoleStoryRoleVo", checkString(id))
    if not vo then
        return false
    end

    return checkNumber(vo.show) == 1
end

