function UIMainBattlePanelDialog:GetCurIndex()
    ---@type UIMainQuestNode
    local scr = CfUtils.GetLuaScr(self.PerspectivePanel, "Game.UI.FightReady.UIMainChapter.UIMainBattlePanel.UIMainQuestNode")
    if scr then
        return scr:GetCurIndex()
    end

end

function UIMainBattlePanelDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self._co then
            cs_coroutine.stop(self._co)
            self._co = nil
        end
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MainHardQuest)
        -- CfUtils.SetUICameraProjection(true)  ---如果回到主界面，主界面onfocus会让资源条倾斜，这里又会让资源条变平，然后主界面第二次onfocus才会让资源条显示正确，会导致切换过程中资源条抖动
        self.controller = nil
        --luabehaviour 中CSharp对象
        self:Delete()
        self = nil
    end))
    return coWait
end

return UIMainBattlePanelDialog
